function groupByFrequency(arr) {
  const freq = {};
  for (const num of arr) freq[num] = (freq[num] || 0) + 1;
  const groups = {};
  for (const [num, count] of Object.entries(freq)) {
    (groups[count] = groups[count] || []).push(Number(num));
  }
  return groups;
}
